import{_ as e,o,c as r,a2 as n}from"./chunks/framework.CdjpmwdR.js";const d=JSON.parse('{"title":"敏捷开发、Agent、ThoughtWorks","description":"从敏捷实践、Agent 协作和 ThoughtWorks 的训练方式，回看软件团队真正依赖的能力：对齐、拆解、表达与建模。","frontmatter":{"category":"domain","title":"敏捷开发、Agent、ThoughtWorks","date":"2026-06-09","description":"从敏捷实践、Agent 协作和 ThoughtWorks 的训练方式，回看软件团队真正依赖的能力：对齐、拆解、表达与建模。","tags":["domain","agile","agent","ThoughtWorks"],"image":null},"headers":[],"relativePath":"blogs/2026/202606-agile-agent-thoughtworks.md","filePath":"blogs/2026/202606-agile-agent-thoughtworks.md"}'),a={name:"blogs/2026/202606-agile-agent-thoughtworks.md"};function g(s,t,l,i,p,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h2 id="敏捷宣言" tabindex="-1">敏捷宣言 <a class="header-anchor" href="#敏捷宣言" aria-label="Permalink to &quot;敏捷宣言&quot;">​</a></h2><p>为什么很多团队无法达成真正的敏捷开发？</p><p>因为<strong>敏捷对人的要求很高</strong>。</p><ul><li>“个体和互动 高于 流程和工具”，要求大家语言一致，理解一致，最好我说半句，你就知道后半句是什么。</li><li>“工作的软件 高于 详尽的文档”，要求大家对代码足够熟，不然没有文档，心里就发虚。</li><li>“客户合作 高于 合同谈判”，要求大家能理解需求，知道客户嘴上说的是什么，背后真正要的又是什么。</li><li>“响应变化 高于 遵循计划”，要求大家既能快速执行，又能在未知领域里不乱掉。</li></ul><p>说到底，这些话的意思都是一样的：团队成员要有比较一致的<strong>业务能力、技术能力和协作能力</strong>。最好你一个眼神，我就 get 到你是想创建接口、重构实现，还是准备砍需求、改设计。</p><p>这是个很高的要求。</p><h2 id="敏捷工程实践" tabindex="-1">敏捷工程实践 <a class="header-anchor" href="#敏捷工程实践" aria-label="Permalink to &quot;敏捷工程实践&quot;">​</a></h2><p>看一眼敏捷宣言的签署者名单，也确实，他们大概是有这个能力和认知的。</p><p>但现实是，你是不可能在招聘市场上找到 Martin Fowler、Kent Beck 的；你也没法克隆你自己，来组成一个共享脑电波的团队。</p><p>所以，我们才需要各种敏捷的<strong>仪式</strong>：Standup、IPM、Sprint Review、Retrospective、Backlog Refinement；各种技术<strong>实践</strong>：Pair Programming、TDD、重构、Code Review。</p><p>当然，通常被吐槽“假敏捷”的对象，也是这些“仪式”：站会过流水账，评审开成老板秀，回顾是吐槽大会，结对成了示范表演，Code Review 成了一起来找茬。</p><p>因为本质上，这些活动都是为了达成敏捷宣言里那个高要求：<strong>同认知、同能力</strong>。</p><ul><li><strong>降低任务复杂度的上限</strong>。Backlog Refinement、IPM 先做需求分析、任务拆分，再靠各种会议同步信息、传递上下文，尽量别让大家各自脑补，最后做出来五个版本。</li><li><strong>提升团队能力的下限</strong>。Pair、mentor、分享、Code Review，本质上都是在做人才梯队，让新加入的同事尽快接近平均能力线，而不是全靠几个老师傅硬撑。</li></ul><p>一上一下，把团队的能力提升到基线以上，你才能谈后面的东西：迭代式开发、估点、自由捡卡、Trunk-Based 开发、自动化测试替代一部分 Code Review。</p><h2 id="agent-as-colleague" tabindex="-1">Agent as Colleague <a class="header-anchor" href="#agent-as-colleague" aria-label="Permalink to &quot;Agent as Colleague&quot;">​</a></h2><p><strong>Agent 的能力</strong>，当然还是取决于使用者的能力和技巧。你问得清不清楚，拆得好不好，约束写没写明白，差别会很大。</p><p>和人一样，你需要去训练它，培养它，甚至是管理它。你得让它知道什么样的结果是好结果，什么样的结果是坏结果；你得让它知道什么样的行为是被鼓励的，什么样的行为是被禁止的；你得让它知道什么样的目标是重要的，什么样的目标是次要的。</p><p>另外，Agent 还具备两个人类同事没有的特点：</p><p>一个是，它的能力可以<strong>大量复制</strong>。Multi-Agent、Sub-Agent 可以并行跑起来。你不是多了一个助手，你是多了一个可以随时拉起来的小队。</p><p>另一个是，它的能力几乎可以<strong>即时获得</strong>。Skills 即插即用，你不需要等新人培训。装上 Frontend Skill，马上就能帮你写 React 组件。</p><p>如果把 Agent 当成团队成员来看，你会发现它天然接近敏捷的需要：<strong>同认知、同能力</strong>，而且还能横向扩容、纵向升级。</p><ul><li>“个体和互动 高于 流程和工具” —— 某种意义上，真的就是 chat with agent。</li><li>“工作的软件 高于 详尽的文档” —— agent 会去读你的代码，而且通常读得很认真。</li><li>“客户合作 高于 合同谈判” —— 你不用谈判，你自己就是需求方。</li><li>“响应变化 高于 遵循计划” —— 你随时改主意，它就跟着重跑。</li></ul><h2 id="_200x" tabindex="-1">200x?? <a class="header-anchor" href="#_200x" aria-label="Permalink to &quot;200x??&quot;">​</a></h2><p>上个月，我利用 Agent 重写了一个内部工具。<strong>1 human + 3~5 Agents</strong> 的团队组合，最后评估出来的<strong>效率提升接近 200x</strong>。</p><p>这个数字单看，确实有点夸张，像某种卖课营销号。</p><p>但如果你把这些 Agents 都当成真实可协作的同事来看，这件事就没那么玄了。无非是一个 6 人的全功能团队：1 个 PO/BA，加上 5 个 developer/tester。</p><p>这样一拆，平均下来，也就是 30x 左右。</p><p>再往下算，还有很多以前默认会消耗的时间被省掉了：会议、培训、上下文同步、等人、找人、休息、吃饭。硅基生物毕竟只吃电，不吃外卖。</p><p>再平均一下，可能也就<strong>10x</strong> —— 顶尖程序员可以达成的量级。</p><p>所以，Agent 不只是代码写得快。更重要的是，它是以团队的方式在工作。它的效率提升，来源于它在多个维度上放大了人的能力：<strong>执行力、协作力、学习力</strong>。</p><blockquote><p>如果你对这个 rewrite 的过程感兴趣，也可以看我前面那篇 <a href="./202605-spdd-agentic-refactor">从数月到一周：Agent Coding 的治理闭环</a>。</p></blockquote><h2 id="thoughtworks" tabindex="-1">ThoughtWorks <a class="header-anchor" href="#thoughtworks" aria-label="Permalink to &quot;ThoughtWorks&quot;">​</a></h2><p>ThoughtWorks 是一家优秀的公司。很多时候，它更像一所大学。</p><p>现在回头看，在 ThoughtWorks 里的典型成长路线，是 “<strong>Thought Worker</strong>”：先分析，再思考，最后才是写代码。</p><p>我们那时候很看重敏捷、<strong>Pair、TDD、DDD</strong> 这类训练，每天讨论建模、分析、评估，各种框架和方法论。</p><p>以前有一段时间，我其实也会疑惑：为什么要花这么多时间在这些和写代码不相关的事情上？直接 CRUD 不好吗？</p><p>现在再看，这些能力恰恰决定了你能带出的<strong>Agent 团队</strong>的规模和质量。</p><p>作为 Tech Lead，你个人能力再强，也未必能稳定做到 10x 于别人。</p><p>能不能把问题定义清楚，能不能做好拆解，能不能识别边界和风险，能不能把模糊需求变成稳定约束，却决定了你能不能带出 10x 团队。</p><ul><li>Pair、TDD、DDD 分别训练沟通协作、边界识别、抽象建模，敏捷训练反馈和调整。</li><li>就连当初的“博客大赛”，现在回头看，锻炼的也不只是写作能力。它训练的是<strong>表达能力</strong>：把你脑子里的东西讲清楚。放到今天，这就是和 Agent 准确沟通的必须技能。</li></ul><p>某种意义上，<strong>“1 带 8”</strong> 在另一个维度实现了。</p>',41)])])}const c=e(a,[["render",g]]);export{d as __pageData,c as default};
